"""Build drill-down test pages and consistent navigation from preserved execution data."""
import ast,hashlib,html,json,posixpath,re
from pathlib import Path
from evidence_format import mask
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'dashboard'
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def esc(v):return html.escape(str(v))
def safe(v):
 s=mask(str(v));s=re.sub(r'(?i)(Bearer\s+)\S+',r'\1[REDACTED]',s)
 return s
NAV=[('Overview','index.html'),('Defect discovery','defects.html'),('Audio comparison','audio-comparison.html'),('Robustness','metrics/robustness.html'),('All test cases','test-cases.html'),('SDK coverage','sdk-coverage.html'),('Ybbag harness','adaptive.html'),('Compliance checks','compliance.html'),('How to use the agent','agent-guide.html'),('Calls','calls.html'),('Test data','data-library.html'),('Test runs','runs.html'),('ASR metrics','metrics/asr.html'),('LLM metrics','metrics/llm.html')]
STYLE='body{margin:0;background:#edf2f3;color:#19343c;font:15px/1.6 system-ui}header{background:#163d44;color:white;padding:28px 4vw}nav{display:flex;gap:14px;flex-wrap:wrap}header a{color:#bae5d9}main{max-width:1250px;margin:auto;padding:24px}a{color:#137269}section,article{background:white;border:1px solid #dbe4e6;border-radius:12px;padding:22px;margin:18px 0}table{width:100%;border-collapse:collapse}td,th{padding:10px;text-align:left;vertical-align:top;border-bottom:1px solid #dbe4e6}.scroll{overflow:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#183c43;color:white;padding:18px;border-radius:8px}input,select{font:inherit;padding:8px;margin:5px}h1{font-size:30px}.status{font-weight:bold}.fail{color:#ae3046}.pass{color:#1c7050}.muted{color:#566d74}'
def nav(path):return '<nav aria-label="Evaluation pages" style="display:flex;flex-wrap:wrap;gap:10px 18px;margin:16px 0">'+' '.join('<a href="'+posixpath.relpath(target,posixpath.dirname(path) or '.')+'">'+label+'</a>' for label,target in NAV)+'</nav>'
def page(path,title,body,script=''):
 p=D/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AEGIS | '+esc(title)+'</title><style>'+STYLE+'</style></head><body><header>'+nav(path)+'<h1>'+esc(title)+'</h1></header><main>'+body+'</main>'+script+'</body></html>\n',encoding='utf-8')
def group(row):
 source=row.get('SourcePath','');kind=row['SourceType'];ident=row['ID'].rsplit('.',1)[-1].lower()+' '+Path(row.get('SourcePath','')).stem.lower()
 if kind=='Executable methods':
  category='Application regression' if source.startswith('tests/functional') else 'SDK contracts'
  stages=[('payment','Payments / consent / idempotency'),('book','Appointments / booking'),('identity','Identity / session isolation'),('verification','Identity / verification'),('credential','Identity / verification'),('journal','Lifecycle / evidence logging'),('call_labels','Evaluation / call labels'),('evaluation','Evaluation / scoring'),('sensitive','Security / sensitive data'),('security','Security / authorization'),('tenacity','Campaign / Agentic Tenacity'),('set_task','Task assignment / checklist'),('task','Task state / completion'),('field','Field collection / validation'),('persona','Persona / conversation policy'),('variable','Conversation variables'),('callback','Callbacks / state'),('helper','Helpers / intent / retrieval'),('datetime','Helpers / scheduling'),('rag','Helpers / retrieval'),('transfer','Telephony command contracts'),('voicemail','Telephony command contracts'),('callback','Callbacks / state'),('install','Installation / version baseline')]
  stage=next((s for token,s in stages if token in ident),'Workflow handlers / task state' if 'handler' in ident else row['PipelineStage'])
  return category,stage
 return kind,row.get('PipelineStage','Not assigned')
rows=read(D/'test-inventory.json')['rows'];history=read(D/'run-history.json')
for suite,label in [('hosted','Hosted workflows'),('security','Hosted security')]:
 run=next((x for x in reversed(history) if x['suite']==suite),None)
 if run:
  for g in run['groups']:
   rows.append({'ID':suite.upper()+':'+g['group'],'SourceType':label,'Status':g['status'],'SourcePath':next((s for s in g.get('command',[]) if str(s).startswith('tests/')),''),'Evidence':g.get('evidence_file',''),'RunCommand':' '.join(g.get('command',[])),'Threat_or_behavior':g['group'],'Expected':'Acceptance assertions in the source runner must pass; process success alone is insufficient.','PipelineStage':'Hosted conversation / workflow outcome' if suite=='hosted' else 'Hosted conversation / authorization','ExecutionReason':'Latest '+suite+' suite only; run '+run['run_id'],'RunId':run['run_id']})
diagnostic_path=D/'appointment-diagnostic.json'
if diagnostic_path.exists():
 diag=read(diagnostic_path)
 for name in ('focused-offline','hosted-appointments'):
  result=diag[name]
  rows.append({'ID':'APPT-DIAG:'+name,'SourceType':'Diagnostic follow-ups','Status':result['status'],'SourcePath':'tests/integration/trace_appointments.py','Evidence':result['evidence'],'RunCommand':'& .\\baseline\\sdk-0.47.0\\.venv\\Scripts\\python.exe tests/integration/trace_appointments.py','Threat_or_behavior':'Appointment handler check' if name=='focused-offline' else 'Same-patient appointment intent matched switch_patient; hosted timeout','Expected':'Retain verified patient and complete the booking flow.','PipelineStage':'Mocked task handlers' if name=='focused-offline' else 'Hosted intent / action request / authorization','ExecutionReason':'Focused follow-up; separate from previous complete hosted suite. See appointment diagnostic report.'})
for row in rows:
 row['Category'],row['Stage']=group(row);row['DetailURL']='cases/'+hashlib.sha256(row['ID'].encode()).hexdigest()[:16]+'.html'
 proof=''
 source=ROOT/row.get('SourcePath','')
 if row['SourceType']=='Executable methods' and source.is_file():
  tree=ast.parse(source.read_text(encoding='utf-8-sig'));name=row['ID'].rsplit('.',1)[-1]
  method=next((n for n in ast.walk(tree) if isinstance(n,ast.FunctionDef) and n.name==name),None)
  if method:
   lines=source.read_text(encoding='utf-8-sig').splitlines();snippet='\n'.join(lines[method.lineno-1:method.end_lineno]);proof='<h2>Actual method and assertions</h2><pre>'+esc(safe(snippet))+'</pre><p>Local source: '+esc(row['SourcePath'])+'; line '+str(method.lineno)+'. This method may contain multiple subcases, counted once.</p>'
  proof+='<p>Raw baseline files are kept locally under evidence/2026-10-11/suite-runs/'+esc(row['Evidence'])+'/ (SDK-offline.txt or Application-functional.txt). A passing mocked method does not prove hosted dialogue or PSTN behavior.</p>'
 elif row['SourceType'] in ('Hosted workflows','Hosted security'):
  raw=ROOT/row['Evidence'];observations=[]
  if raw.is_file():
   for line in raw.read_text(encoding='utf-8',errors='replace').splitlines():
    try:o=json.loads(line)
    except (ValueError,TypeError):continue
    if isinstance(o,dict) and any(k in o for k in ('transcript','outcomes','outcome')):observations.append(o)
   proof='<h2>Preserved observed outcome / transcript</h2><pre>'+esc(safe(json.dumps(observations,indent=2)))+'</pre><p>Raw file SHA-256: '+hashlib.sha256(raw.read_bytes()).hexdigest()+'. Raw service/debug logs are not published.</p>'
 body='<p><a href="../test-cases.html">All cases</a></p><article><p class="status">'+esc(row['Status'])+'</p><p>'+esc(row['Category'])+' / '+esc(row['Stage'])+'</p><h2>Scenario</h2><p>'+esc(safe(row.get('Threat_or_behavior','')))+'</p><h2>Expected behavior</h2><p>'+esc(safe(row.get('Expected','')))+'</p><h2>Execution scope</h2><p>'+esc(row.get('ExecutionReason','See preserved evidence; status is not a blanket product verdict.'))+'</p><p>Source: '+esc(row.get('SourcePath',''))+'<br>Evidence: '+esc(row.get('Evidence',''))+'</p>'+proof+'<h2>Run command</h2><pre>'+esc(row.get('RunCommand','See Test runs'))+'</pre></article>'
 if row['SourceType']=='Diagnostic follow-ups':body+='<p><a href="../../reports/test-results/appointments-diagnostic-2026-10-12.md">Actual routing trace and diagnostic evidence</a></p>'
 if row['SourceType']=='Audio review cases':body+='<p><a href="../audio-review.html">Listen to captured output and review verdict</a></p>'
 if row['SourceType']=='Audio fixtures':body+='<p><a href="../audio-comparison.html">Measured audio comparisons and limitations</a> / <a href="../audio-backlog.html">Fixture observations</a></p>'
 if row['SourceType']=='Text prompts':body+='<p><a href="../defects.html">Reviewed defect evidence</a> / <a href="../compliance.html">Representative authority cases</a></p>'
 page(row['DetailURL'],row['ID'],body)
(D/'case-catalog.json').write_text(json.dumps({'rows':rows,'note':'Separate inventories, no pooled pass rate'},indent=2),encoding='utf-8')
body='<section><p>Every row is clickable. Filter by intended use, pipeline stage and actual recorded status. Plans, executable methods, hosted scenarios and audio observations use different acceptance rules. PASS applies only to recorded assertions; OBSERVED is not PASS.</p><p><a href="?category=Application%20regression">32 application methods</a> / <a href="?category=SDK%20contracts">53 SDK methods</a> / <a href="?category=Hosted%20workflows">Hosted workflow results</a> / <a href="?category=Hosted%20security">Hosted security results</a> / <a href="?status=FAIL">Failed checks (FAIL)</a> / <a href="?status=PASS">Passed checks (PASS)</a> / <a href="?outcome=failures">All failure statuses and timeouts</a></p><label>Use <select id="category"><option value="">All categories</option></select></label><label>Stage <select id="stage"><option value="">All stages</option></select></label><label>Status <select id="status"><option value="">All statuses</option></select></label><input id="search" placeholder="Search case or scenario" aria-label="Search cases"><p id="count" aria-live="polite"></p><div class="scroll"><table><thead><tr><th>Case / details</th><th>Use / stage</th><th>Actual result</th><th>Scenario</th></tr></thead><tbody id="rows"></tbody></table></div></section>'
page('test-cases.html','All test cases and results',body,'<script src="case-catalog.js"></script>')
(D/'case-catalog.js').write_text('''const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));fetch('case-catalog.json',{cache:'no-store'}).then(r=>r.json()).then(d=>{const p=new URLSearchParams(location.search);for(const [id,key] of [['category','Category'],['stage','Stage'],['status','Status']]){const n=document.getElementById(id);for(const v of [...new Set(d.rows.map(r=>r[key]))].sort())n.add(new Option(v,v));if(p.has(id))n.value=p.get(id);n.onchange=render;}document.getElementById('search').oninput=render;function render(){const q=document.getElementById('search').value.toLowerCase();const rows=d.rows.filter(r=>(p.get('outcome')!=='failures'||r.Status.includes('FAIL')||r.Status==='TIMEOUT')&&(!document.getElementById('category').value||r.Category===document.getElementById('category').value)&&(!document.getElementById('stage').value||r.Stage===document.getElementById('stage').value)&&(!document.getElementById('status').value||r.Status===document.getElementById('status').value)&&JSON.stringify(r).toLowerCase().includes(q));document.getElementById('count').textContent=rows.length+' / '+d.rows.length+' inventory entries';document.getElementById('rows').innerHTML=rows.map(r=>'<tr><td><a href="'+e(r.DetailURL)+'">'+e(r.ID)+'</a></td><td>'+e(r.Category)+'<br>'+e(r.Stage)+'</td><td class="status '+(r.Status.includes('FAIL')?'fail':r.Status==='PASS'?'pass':'')+'">'+e(r.Status)+'</td><td>'+e(r.Threat_or_behavior)+'</td></tr>').join('');}render();}).catch(()=>document.getElementById('count').textContent='Result inventory unavailable; no statuses inferred.');\n''',encoding='utf-8')
# Standalone pages for each robustness card, with links to actual underlying observations.
details=[('Application regression','application','32 deterministic methods test synthetic handlers, authorization, bookings, payments and lifecycle. They do not exercise ASR or PSTN.','test-cases.html?category=Application%20regression'),('Hosted text attacks','security','The latest fixed-turn attack suite passed injection and malformed-input checks, but failed identity-switch. Native rubric results and independent safety findings are separate.','test-cases.html?category=Hosted%20security'),('Speech fixtures','speech','24 input corpus entries have scoped observations. Clean, noisy and echo conditions use labeled references. Recognition observations are not complete workflow passes.','audio-backlog.html'),('Human accents / dialects','accents','NOT_RUN: the current small public/synthetic corpus is not a representative accent or dialect sample. Need consent/licensing, speaker/accent labels, reference transcripts and balanced coverage.','data-library.html'),('Echo / overlap probes','echo','Delayed file echo corrupted both credential strings twice. This is recognition evidence, not an isolated acoustic echo-cancellation or live interruption measurement.','../reports/findings/evidence/ROB-003.md'),('Playback diagnostic','playback','User confirmed hearing a captured synthetic greeting. That validates local browser playback only, not microphone capture, PSTN or native audio-device selection.','metrics/robustness.html'),('Public human-speech conditions','public','Four public source utterances have paired clean/noise/echo observations. Small clips and shared sources do not establish population accuracy or accent coverage. Inspect transcripts and per-sample edits.','audio-comparison.html')]
for title,slug,text,target in details:
 body='<article><h2>What this evaluates</h2><p>'+esc(text)+'</p><p><a href="'+posixpath.relpath(target,'robustness')+'">Open actual cases / evidence</a></p><h2>How to interpret the result</h2><p>A scoped observation is not a guarantee. Different speakers, timings, transports and repeated trials may change the outcome. Keep failures and raw evidence; do not turn an unmeasured condition into PASS.</p></article>'
 if slug=='playback':body+='<audio controls src="../assets/captured-demo-greeting.wav"></audio>'
 page('robustness/'+slug+'.html',title,body)
p=D/'metrics/robustness.html';s=p.read_text(encoding='utf-8')
for title,slug,_,_ in details:s=s.replace('<h2>'+title+'</h2>','<h2><a href="../robustness/'+slug+'.html">'+title+'</a></h2>')
p.write_text(s,encoding='utf-8')
guide='''<section><h2>Learn the system and findings</h2><p><a href="../docs/understanding-aegis-care.md">Plain-language faults, test overview and end-to-end flowchart</a></p></section><section><h2>Start a synthetic call</h2><p>HarborCare is the patient-facing prototype; AEGIS Care is the evaluation project. Use patient ID <strong>1001</strong>, verification code <strong>4242</strong>. Speak each digit separately. Never supply real healthcare information or cards.</p><p>The existing inbound number is +1 240-225-1787. Phone and WebRTC need separate running listeners. Browser calls may still use hosted minutes. One workflow is completed per call; the agent then hangs up.</p><pre>Set-Location C:\\Users\\prana\\aegis-care\n.\\tests\\manual\\start-manual-validation.ps1 -Channel phone\n# Or: -Channel webrtc / -Channel text</pre></section><section><h2>What you can request</h2><table><tr><th>Workflow</th><th>Say after verification</th><th>Synthetic behavior</th></tr><tr><td>Identity</td><td>Please confirm my identity.</td><td>Same-patient confirmation; wrong-account routing is a known finding.</td></tr><tr><td>Insurance</td><td>I want to check insurance eligibility.</td><td>Synthetic Bronze coverage, active; no live insurer integration.</td></tr><tr><td>Claims</td><td>I want to check my claim status.</td><td>Demo pending claim; latest hosted claims scenario failed, so reliability is not established.</td></tr><tr><td>Appointments</td><td>I want to book an appointment for myself, the same patient.</td><td>Two synthetic October 15, 2026 slots; choose a currently available slot. No real clinic calendar.</td></tr><tr><td>Billing</td><td>What is my outstanding balance?</td><td>Initially 50 dollars for patient 1001; simulated payment can change it within the running backend.</td></tr><tr><td>Payment</td><td>I consent to a simulated payment of 1000 cents.</td><td>No real charge; simulated token only; must not request/read back full card/CVV.</td></tr></table></section><section><h2>Appointment manual script</h2><ol><li>Start a fresh call. Wait for the greeting.</li><li>Say: My patient ID is one zero zero one. My verification code is four two four two.</li><li>Wait until verification finishes and the agent asks what you need.</li><li>Say: I want to book an appointment for myself, the same patient I just verified.</li><li>Ask: What appointment slots are available?</li><li>If offered, say: Book October fifteenth, twenty twenty-six, at nine AM. If already taken, choose the offered two PM slot.</li><li>Expect explicit appointment confirmation and courteous closure. Record the exact response, call ID and whether it asked for a different account.</li></ol><p>Comparison call: repeat with the natural phrase “Can you schedule my appointment?” If only one wording fails, preserve both recordings. Do not provide another patient's details to bypass a wrong-account prompt.</p><p>Booking logic exists. The account-switch callback can clear verified state after an intent match; the focused diagnostic captured “I choose appointments” matching switch_patient. The code clears verification immediately, and the hosted run timed out. The exact original phone-call linkage remains unverified. Passing a scripted text booking does not prove phone success. Shared in-memory slots can be consumed by earlier calls and reset on restart; timezone, real scheduling and production persistence are not implemented.</p><p><a href="../reports/test-results/appointments-diagnostic-2026-10-12.md">Appointment diagnostic evidence</a> / <a href="../docs/manual-validation-script.md">Eight manual fault-validation cases</a></p></section>'''
page('agent-guide.html','How to use HarborCare',guide)
