for p in D.rglob('*.html'):
 if '.venv' in p.parts:continue
 rel=p.relative_to(D).as_posix();s=p.read_text(encoding='utf-8');s=re.sub(r'<nav\b[^>]*>.*?</nav>',lambda _:nav(rel),s,count=1,flags=re.S);p.write_text(s,encoding='utf-8')
